#include <algorithm>
#include <queue>
#include <string>
#include <utility>
#include <vector>

using Path = std::vector<std::pair<int, int>>;

Path findPath(const std::vector<std::string>& map, int sx, int sy, int tx, int ty)
{
    const int h{ static_cast<int>(map.size()) };
    const int w{ h > 0 ? static_cast<int>(map[0].size()) : 0 };
    auto index = [w](int x, int y) { return static_cast<std::size_t>(y * w + x); };
    std::vector<int> cameFrom(static_cast<std::size_t>(w * h), -2);      // -2: not reached
    std::queue<std::pair<int, int>> frontier;
    cameFrom[index(sx, sy)] = -1;                                        // -1: the start
    frontier.push({ sx, sy });
    const int dx[]{ 1, -1, 0, 0 }, dy[]{ 0, 0, 1, -1 };
    while (!frontier.empty())
    {
        const auto [x, y] = frontier.front();
        frontier.pop();
        if (x == tx && y == ty)
        {
            Path path;
            for (int at{ static_cast<int>(index(x, y)) }; at != -1; at = cameFrom[static_cast<std::size_t>(at)])
                path.push_back({ at % w, at / w });
            std::reverse(path.begin(), path.end());
            return path;
        }
        for (int d{ 0 }; d < 4; ++d)
        {
            const int nx{ x + dx[d] }, ny{ y + dy[d] };
            if (nx < 0 || ny < 0 || nx >= w || ny >= h || map[ny][nx] == '#') continue;
            if (cameFrom[index(nx, ny)] != -2) continue;
            cameFrom[index(nx, ny)] = static_cast<int>(index(x, y));
            frontier.push({ nx, ny });
        }
    }
    return {};
}

