#include <cstdlib>
static bool validPath(const std::vector<std::string>& map, const Path& p, int sx, int sy, int tx, int ty)
{
    if (p.empty() || p.front() != std::pair{ sx, sy } || p.back() != std::pair{ tx, ty }) return false;
    for (std::size_t i{ 0 }; i < p.size(); ++i)
    {
        const auto [x, y] = p[i];
        if (y < 0 || y >= static_cast<int>(map.size()) || x < 0 || x >= static_cast<int>(map[y].size()) || map[y][x] == '#') return false;
        if (i > 0 && std::abs(x - p[i - 1].first) + std::abs(y - p[i - 1].second) != 1) return false;
    }
    return true;
}
const std::vector<std::string> maze{ "#########", "#M..#...#", "#.#.#.#.#", "#.#...#P#", "#########" };
TEST("a path through the maze") { const Path p{ findPath(maze, 1, 1, 7, 3) }; CHECK(validPath(maze, p, 1, 1, 7, 3)); CHECK_EQ(p.size(), std::size_t{ 13 }); }
TEST("start is the target") { const Path p{ findPath(maze, 3, 1, 3, 1) }; CHECK_EQ(p.size(), std::size_t{ 1 }); CHECK(p[0] == std::pair{ 3, 1 }); }
TEST("unreachable") { const std::vector<std::string> m{ ".#.", ".#.", ".#." }; CHECK(findPath(m, 0, 0, 2, 2).empty()); }
TEST("open field takes the direct number of steps")
{
    const std::vector<std::string> m(5, std::string(6, '.'));
    const Path p{ findPath(m, 0, 0, 5, 4) };
    CHECK(validPath(m, p, 0, 0, 5, 4));
    CHECK_EQ(p.size(), std::size_t{ 10 });
}
TEST("around a wall")
{
    const std::vector<std::string> m{ "....", ".##.", "...." };
    const Path p{ findPath(m, 0, 1, 3, 1) };
    CHECK(validPath(m, p, 0, 1, 3, 1));
    CHECK_EQ(p.size(), std::size_t{ 6 });
}

